  expect(await exportedPixel(page, 400, 312)).toEqual([0, 0, 255, 255]);
  await page.getByRole('button', { name: 'Redo' }).click();
  expect(await exportedPixel(page, 400, 312)).toEqual([18, 18, 18, 255]);

