+export interface CloneStampSource {
+  readonly layer: PixelLayer;
+  /** World transform of the source layer in document space. */
+  readonly worldTransform: LayerTransform;
+  /** Document-space source origin established by Alt/Option-click. */
+  readonly originX: number;
+  readonly originY: number;
+}
+
+export interface CloneStampOptions {
+  readonly size: number;
+  readonly hardness: number;
+  readonly opacity: number;
+  /** When true the source offset is preserved across stroke segments. */
+  readonly aligned: boolean;
