+ * Samples pixels from a source layer and paints them into a destination layer
+ * using the same document-space brush falloff model as paintStroke. The source
+ * origin is interpreted in document space and inverse-mapped into the source
+ * layer's local coordinates. Aligned mode offsets the source by the distance
+ * from the gesture start; unaligned mode always reads from the fixed origin.
+ * A missing or null source returns a zero-area patch.
+ */
+export function cloneStampStroke(
+  destination: PixelLayer,
+  points: readonly BrushPoint[],
+  options: CloneStampOptions,
+  source: CloneStampSource | null,
+  selection?: SelectionMask | null,
+  worldTransform: LayerTransform = destination.transform,
+): PixelPatch {
+  validateLayer(destination);
+  validateTransform(worldTransform);
+  validateSelection(selection);
+  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');
+  assertFinite(options.size, 'Clone stamp size');
+  if (options.size <= 0) throw new RangeError('Clone stamp size must be greater than 0');
+  assertUnit(options.hardness, 'Clone stamp hardness');
+  assertUnit(options.opacity, 'Clone stamp opacity');
+  for (const [index, point] of points.entries()) {
+    assertFinite(point.x, `Stroke point ${String(index)} x`);
+    assertFinite(point.y, `Stroke point ${String(index)} y`);
+    assertUnit(point.pressure ?? 1, `Stroke point ${String(index)} pressure`);
+  }
+  if (source === null) return emptyPatch();
+
+  const radius = options.size / 2;
+  const inverse = invertTransform(worldTransform);
+  const spacing = Math.max(0.25, radius * 0.5);
+
+  // Pre-compute the source layer local-space inverse so every dab avoids
+  // re-inverting the same matrix.
+  const sourceInverse = invertTransform(source.worldTransform);
