                saturation: draft.saturation,
                lightness: draft.lightness,
              },
            } as const)
          : draft.kind === 'invert'
            ? ({ kind: 'invert' } as const)
            : draft.kind === 'grayscale'
              ? ({ kind: 'grayscale' } as const)
              : draft.kind === 'threshold'
                ? ({ kind: 'threshold', level: draft.threshold } as const)
