  const regionTop = strokeBounds.top;
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const next = destination.pixelStore.read({
    x: regionLeft,
    y: regionTop,
    width: regionWidth,
    height: regionHeight,
  });
  const selectionRegion = readSelectionRegion(selection, dabs, radius);
  let changedBounds: Bounds | null = null;

  for (let dabIndex = 0; dabIndex < dabs.length; dabIndex += 1) {
    const dab = dabs[dabIndex];

    // Update the effective source origin for aligned mode.
    if (options.aligned && dabIndex > 0) {
      const dx = dab.x - firstDab.x;
      const dy = dab.y - firstDab.y;
      effectiveOriginX = source.originX + dx;
      effectiveOriginY = source.originY + dy;
    }

    // Compute the source layer local coordinate for this dab.
    const sourceLocal = transformPoint(sourceInverse, effectiveOriginX, effectiveOriginY);

    const bounds = localDabBounds(
      worldTransform,
      inverse,
      dab.x,
      dab.y,
      radius,
      destination.width,
      destination.height,
    );
    const { left, top, right, bottom } = bounds;
    for (let y = top; y <= bottom; y += 1) {
      for (let x = left; x <= right; x += 1) {
        const documentPoint = transformPoint(worldTransform, x, y);
        const falloff = dabCoverage(
          Math.hypot(documentPoint.x - dab.x, documentPoint.y - dab.y),
          radius,
          options.hardness,
        );
        const selected = selectionCoverage(
          selection,
          documentPoint.x,
          documentPoint.y,
          selectionRegion.buffer,
          selectionRegion.region,
        );
        const coverage = falloff * options.opacity * dab.pressure * selected;
        if (coverage <= 0) continue;

        // Sample the source layer at the equivalent local offset.
        const sourceDx = documentPoint.x - dab.x;
        const sourceDy = documentPoint.y - dab.y;
        const sampleX = Math.round(sourceLocal.x + sourceDx);
        const sampleY = Math.round(sourceLocal.y + sourceDy);
        const sample = [
          pixelStoreSample(source.layer, sampleX, sampleY, 0),
          pixelStoreSample(source.layer, sampleX, sampleY, 1),
          pixelStoreSample(source.layer, sampleX, sampleY, 2),
          pixelStoreSample(source.layer, sampleX, sampleY, 3),
